21	const COMPONENT_TYPES = new Set(["rune", "moonstone"]);
22	const COMPONENT_BLOCK_SIZE = 3;
23	const COMPONENT_BLOCK_PREMIUM = 60;
24	
25	function formsComponentBlock(type: string, count: number): boolean {
26	  return COMPONENT_TYPES.has(type) && count === COMPONENT_BLOCK_SIZE;
27	}
28	
29	function premiumForTypeGroup(type: string, count: number): number {
30	  return formsComponentBlock(type, count)
31	    ? COMPONENT_BLOCK_PREMIUM
32	    : ITEM_BASE_PREMIUM[type] * count;
33	}
