43	const CURSE_SURCHARGE = 0.5;
44	const HIGH_ENCHANTMENT_SURCHARGE = 0.3;
45	const HIGH_ENCHANTMENT_THRESHOLD = 5;
46	
47	function isHighEnchantment(enchantment: number | undefined): boolean {
48	  return enchantment !== undefined && enchantment >= HIGH_ENCHANTMENT_THRESHOLD;
49	}
