51	type InsuredItem = { type: string; material?: string; cursed?: boolean; enchantment?: number };
52	
53	function itemSurchargeRate(item: InsuredItem): number {
54	  const curseRate = item.cursed ? CURSE_SURCHARGE : 0;
55	  const enchantmentRate = isHighEnchantment(item.enchantment) ? HIGH_ENCHANTMENT_SURCHARGE : 0;
56	  return curseRate + enchantmentRate;
57	}
58	
59	function itemBasePremium(item: InsuredItem): number {
60	  return ITEM_BASE_PREMIUM[item.type];
61	}
62	
63	function itemPolicyPremium(item: InsuredItem): number {
64	  return itemBasePremium(item) * (1 + itemSurchargeRate(item));
65	}
66	
67	export function policyBasePremium(items: InsuredItem[]): number {
68	  return items.reduce((total, item) => total + itemPolicyPremium(item), 0);
69	}
70	
71	const LOYALTY_DISCOUNT = 0.2;
72	const LOYALTY_YEARS_THRESHOLD = 2;
73	const FIRST_INSURANCE_SURCHARGE = 0.1;
74	const PROCESSING_FEE = 5;
75	
76	type Customer = { yearsWithMHPCO: number };
77	
78	function assertKnownItemTypes(items: InsuredItem[]): void {
79	  const unknownItem = items.find((item) => !KNOWN_ITEM_TYPES.includes(item.type));
80	  if (unknownItem) {
81	    throw new Error(`Unknown item type: ${unknownItem.type}`);
82	  }
83	}
84	
85	function isLoyalCustomer(customer: Customer): boolean {
86	  return customer.yearsWithMHPCO >= LOYALTY_YEARS_THRESHOLD;
87	}
88	
89	const FOLLOWUP_DISCOUNT = 0.15;
90	
91	function policyWideRate(customer: Customer, isFollowUpContract: boolean): number {
92	  const loyaltyRate = isLoyalCustomer(customer) ? LOYALTY_DISCOUNT : 0;
93	  const followupRate = isFollowUpContract ? FOLLOWUP_DISCOUNT : 0;
94	  return FIRST_INSURANCE_SURCHARGE - loyaltyRate - followupRate;
95	}
96	
97	function itemQuotePremium(
98	  item: InsuredItem,
99	  customer: Customer,
100	  isFollowUpContract: boolean
101	): number {
102	  return (
103	    itemBasePremium(item) *
104	    (1 + itemSurchargeRate(item) + policyWideRate(customer, isFollowUpContract))
105	  );
106	}
