108	export function quote(
109	  customer: Customer,
110	  items: InsuredItem[],
111	  isFollowUpContract: boolean = false
112	): number {
113	  assertKnownItemTypes(items);
114	
115	  const premium =
116	    items.reduce((total, item) => total + itemQuotePremium(item, customer, isFollowUpContract), 0) +
117	    PROCESSING_FEE;
118	  return Math.ceil(premium);
119	}
