121	const ITEM_INSURANCE_VALUE: Record<string, number> = {
122	  sword: 1000,
123	  amulet: 600,
124	  staff: 800,
125	  potion: 400,
126	  rune: 250,
127	  moonstone: 250,
128	};
129	
130	const DEDUCTIBLE = 100;
131	const CAP_MULTIPLIER = 2;
132	
133	type PolicyItem = {
134	  type: string;
135	  material?: string;
136	  enchantment?: number;
137	  cursed?: boolean;
138	};
139	type Damage = { itemType: string; amount: number };
140	
141	function insuranceSum(policyItems: PolicyItem[]): number {
142	  return policyItems.reduce((sum, item) => sum + ITEM_INSURANCE_VALUE[item.type], 0);
143	}
144	
145	const HIGH_ENCHANTMENT_DAMAGE_THRESHOLD = 8;
146	const HIGH_ENCHANTMENT_REIMBURSEMENT_RATE = 0.5;
147	const STANDARD_REIMBURSEMENT_RATE = 1;
148	
149	// Dragon-material items are reimbursed at the standard rate today; no test
150	// yet distinguishes them from other materials. Revisit when a dragon-only
151	// clause (e.g. full reimbursement bypassing another reduction) is specified.
152	function reimbursementRate(item: PolicyItem): number {
153	  if (item.enchantment !== undefined && item.enchantment >= HIGH_ENCHANTMENT_DAMAGE_THRESHOLD) {
154	    return HIGH_ENCHANTMENT_REIMBURSEMENT_RATE;
155	  }
156	  return STANDARD_REIMBURSEMENT_RATE;
157	}
158	
159	function damagePayout(damage: Damage, policyItems: PolicyItem[]): number {
160	  const item = policyItems.find((policyItem) => policyItem.type === damage.itemType);
161	  const rate = item ? reimbursementRate(item) : STANDARD_REIMBURSEMENT_RATE;
162	  return damage.amount * rate - DEDUCTIBLE;
163	}
164	
165	function assertNonNegativeDamages(damages: Damage[]): void {
166	  const negativeDamage = damages.find((damage) => damage.amount < 0);
167	  if (negativeDamage) {
168	    throw new Error(`Damage amount cannot be negative: ${negativeDamage.amount}`);
169	  }
170	}
171	
172	function assertDamagesWithinPolicy(policyItems: PolicyItem[], damages: Damage[]): void {
173	  const insuredCounts = countByType(policyItems, (item) => item.type);
174	  const damageCounts = countByType(damages, (damage) => damage.itemType);
175	  for (const [itemType, damageCount] of damageCounts) {
176	    if (damageCount > (insuredCounts.get(itemType) ?? 0)) {
177	      throw new Error(`More damaged items of type ${itemType} than insured`);
178	    }
179	  }
180	}
181	
182	export function claim(
183	  policyItems: PolicyItem[],
184	  damages: Damage[],
185	  priorPayout: number = 0
186	): { payout: number; remainingCap: number } {
187	  assertNonNegativeDamages(damages);
188	  assertDamagesWithinPolicy(policyItems, damages);
189	
190	  const desiredPayout = Math.floor(
191	    damages.reduce((sum, damage) => sum + damagePayout(damage, policyItems), 0)
192	  );
193	  const availableCap = CAP_MULTIPLIER * insuranceSum(policyItems) - priorPayout;
194	  const payout = Math.min(desiredPayout, availableCap);
195	  const remainingCap = availableCap - payout;
196	  return { payout, remainingCap };
197	}
